mapper.select:
SELECT cal_date AS calendarDate,
       content
FROM calendar
WHERE MONTH(cal_date) = #{month}
  AND YEAR(cal_date) = #{year}
  AND user_id = #{userId}

mapper.update:
UPDATE calendar
SET content = #{newContent}
WHERE user_id = #{userId}
  AND cal_date = CONCAT(#{year}, '-', LPAD(#{month}, 2, '0'), '-', LPAD(#{day}, 2, '0'))
  AND content = #{oldContent}

mapper.delete:
DELETE
FROM calendar
WHERE user_id = #{userId}
  AND cal_date = CONCAT(#{year}, '-', LPAD(#{month}, 2, '0'), '-', LPAD(#{day}, 2, '0'))
  AND content = #{content}
